// ============================================================
// Scroll reveal
// ============================================================
function useScrollReveal() {
  useEffect(() => {
    const elements = document.querySelectorAll('.reveal');
    const revealAll = () =>
      elements.forEach((el) => el.classList.add('revealed'));

    if (
      typeof window === 'undefined' ||
      typeof window.matchMedia !== 'function'
    ) {
      revealAll();
      return undefined;
    }
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      revealAll();
      return undefined;
    }
    if (typeof IntersectionObserver === 'undefined') {
      revealAll();
      return undefined;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('revealed');
            observer.unobserve(entry.target);
          }
        });
      },
      { rootMargin: '0px 0px -64px 0px', threshold: 0.08 }
    );

    elements.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);
}

// ============================================================
// Session storage — با کلیدهای مشترک
// ============================================================
function readQuickCalcFromSession() {
  try {
    const savedForm = sessionStorage.getItem(SESSION_KEYS.QUICK_FORM);
    const savedResult = sessionStorage.getItem(SESSION_KEYS.QUICK_RESULT);
    if (savedForm && savedResult) {
      return {
        form: JSON.parse(savedForm),
        result: JSON.parse(savedResult),
      };
    }
  } catch {
    /* Session data is optional. */
  }
  return null;
}

function clearAllPendingSessions() {
  try {
    sessionStorage.removeItem(SESSION_KEYS.QUICK_FORM);
    sessionStorage.removeItem(SESSION_KEYS.QUICK_RESULT);
    sessionStorage.removeItem(SESSION_KEYS.PENDING_ORDER);
    sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
  } catch {
    /* Session storage may be unavailable. */
  }
}

// ============================================================
//  🔄 استخراج dog از پاسخ API
// ============================================================
function normalizeDogResponse(raw) {
  if (!raw) return null;
  const dog = raw.dog || raw;
  if (!dog || !dog.id) return null;
  return dog;
}

// ============================================================
// Address modal — فقط برای کاربر لاگین‌کرده
// ============================================================
function AddressModal({
  isOpen,
  onClose,
  onConfirm,
  loading,
  initialDelivery = null,
}) {
  const [delivery, setDelivery] = useState({
    city: '',
    address: '',
    lat: null,
    lng: null,
  });

  const closeButtonRef = useRef(null);
  const previousFocusRef = useRef(null);

  useEffect(() => {
    if (!isOpen) return undefined;
    previousFocusRef.current = document.activeElement;

    if (
      initialDelivery?.city &&
      initialDelivery?.address &&
      initialDelivery?.lat != null &&
      initialDelivery?.lng != null
    ) {
      setDelivery({
        city: initialDelivery.city,
        address: initialDelivery.address,
        lat: initialDelivery.lat,
        lng: initialDelivery.lng,
      });
    } else {
      setDelivery({ city: '', address: '', lat: null, lng: null });
    }

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    const focusTimer = window.setTimeout(() => {
      closeButtonRef.current?.focus();
    }, 0);

    const handleKeyDown = (event) => {
      if (event.key === 'Escape' && !loading) onClose();

      if (event.key === 'Tab') {
        const dialog = document.getElementById('address-modal-dialog');
        if (!dialog) return;

        const focusable = dialog.querySelectorAll(
          'button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])'
        );
        if (!focusable.length) return;

        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault();
          last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
          event.preventDefault();
          first.focus();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      window.clearTimeout(focusTimer);
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = previousOverflow;
      if (previousFocusRef.current?.isConnected) {
        previousFocusRef.current.focus();
      }
    };
  }, [isOpen, initialDelivery, loading, onClose]);

  if (!isOpen) return null;

  const isValid = isDeliveryValid(delivery);
  const confirmLabel = 'تأیید آدرس و ثبت سفارش';
  const loadingLabel = 'در حال ثبت سفارش...';

  return (
    <div
      className="fixed inset-0 z-[60] flex items-end justify-center bg-ink-900/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget && !loading) onClose();
      }}
      role="presentation"
    >
      <div
        id="address-modal-dialog"
        className="flex max-h-[95dvh] w-full flex-col overflow-hidden rounded-t-3xl border border-miko-carrot/30 bg-miko-cream shadow-editorial dark:border-dark-700 dark:bg-ink-800 sm:max-h-[90dvh] sm:max-w-2xl sm:rounded-3xl"
        dir="rtl"
        role="dialog"
        aria-modal="true"
        aria-labelledby="address-modal-title"
      >
        <div
          className="mx-auto mt-2 h-1.5 w-12 shrink-0 rounded-full bg-miko-carrot/30 dark:bg-dark-600 sm:hidden"
          aria-hidden="true"
        />

        <header className="flex shrink-0 items-center gap-3 border-b border-miko-carrot/20 bg-miko-carrot/10 p-3.5 dark:border-dark-700 dark:bg-miko-rust/10 sm:p-5">
          <div
            className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br from-miko-rust to-miko-pumpkin p-2.5 text-white shadow-miko"
            aria-hidden="true"
          >
            <SiteImage
              imageKey="icon_location"
              fallback="📍"
              alt=""
              className="w-full h-full object-contain"
            />
          </div>

          <div className="min-w-0 flex-1">
            <h2
              id="address-modal-title"
              className="font-display text-sm font-black text-miko-dark dark:text-cream-100 sm:text-base"
            >
              آدرس تحویل سفارش
            </h2>
            <p className="mt-1 text-xs leading-6 text-miko-dark/60 dark:text-cream-400">
              محل دقیق تحویل رو روی نقشه مشخص کن.
            </p>
          </div>

          <button
            ref={closeButtonRef}
            type="button"
            onClick={onClose}
            disabled={loading}
            className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-lg text-miko-dark/60 transition hover:bg-rose-50 hover:text-rose-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-miko-rust disabled:opacity-50 dark:hover:bg-rose-500/15"
            aria-label="بستن پنجره آدرس"
          >
            ✕
          </button>
        </header>

        <div className="min-h-0 flex-1 overflow-y-auto p-3.5 sm:p-5">
          <DeliveryLocationPicker
            value={delivery}
            onChange={setDelivery}
            disabled={loading}
          />
        </div>

        <footer className="flex shrink-0 flex-col-reverse gap-2.5 border-t border-miko-carrot/20 bg-miko-carrot/5 p-3.5 dark:border-dark-700 dark:bg-ink-900/50 sm:flex-row sm:p-5">
          <button
            type="button"
            onClick={onClose}
            disabled={loading}
            className="min-h-12 w-full rounded-xl border border-miko-carrot/30 bg-white px-5 py-3 text-sm font-bold text-miko-olive transition hover:bg-miko-carrot/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-miko-rust disabled:opacity-50 dark:border-dark-600 dark:bg-ink-700 dark:text-cream-200 sm:w-auto"
          >
            انصراف
          </button>

          <button
            type="button"
            onClick={() => onConfirm(delivery)}
            disabled={!isValid || loading}
            className={`flex min-h-12 w-full items-center justify-center gap-2 rounded-xl px-6 py-3 text-sm font-black transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-miko-rust focus-visible:ring-offset-2 sm:flex-1 ${
              !isValid || loading
                ? 'cursor-not-allowed bg-miko-carrot/15 text-miko-dark/40 shadow-none dark:bg-ink-700 dark:text-cream-500'
                : 'bg-gradient-to-br from-miko-rust to-miko-pumpkin text-white shadow-miko hover:opacity-95 active:opacity-90'
            }`}
          >
            {loading ? (
              <>
                <span
                  className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent"
                  aria-hidden="true"
                />
                <span>{loadingLabel}</span>
              </>
            ) : (
              <>
                <span className="w-4 h-4 flex-shrink-0" aria-hidden="true">
                  <SiteImage
                    imageKey="icon_check"
                    fallback="✓"
                    alt=""
                    className="w-full h-full object-contain"
                  />
                </span>
                <span>{confirmLabel}</span>
              </>
            )}
          </button>
        </footer>
      </div>
    </div>
  );
}

// ============================================================
// Main homepage
// ============================================================
export default function UserApp() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  // dog_id از URL — مثلاً /?dog_id=5#order-form-section
  const urlDogId = searchParams.get('dog_id');

  useScrollReveal();

  // 🛒 cart
  const cart = useCart();

  const [orderData, setOrderData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  const [orderSubmitted, setOrderSubmitted] = useState(false);
  const [submittedOrderId, setSubmittedOrderId] = useState(null);

  const [showAddressModal, setShowAddressModal] = useState(false);
  const [pendingOrderData, setPendingOrderData] = useState(null);
  const [lastDelivery, setLastDelivery] = useState(null);

  const [summaryVisible, setSummaryVisible] = useState(false);
  const [injectedFormData, setInjectedFormData] = useState(null);

  const [initialFormData, setInitialFormData] = useState(() => {
    // اگر dog_id در URL هست، اجازه بده effect پیش‌پرکردن این کار را انجام دهد
    if (urlDogId) return null;
    const data = readQuickCalcFromSession();
    return data?.form || null;
  });

  const isMountedRef = useRef(false);
  const calculationRequestRef = useRef(false);
  const submissionRequestRef = useRef(false);
  const redirectTimerRef = useRef(null);
  const prefetchedDogRef = useRef(null);

  useEffect(() => {
    isMountedRef.current = true;

    return () => {
      isMountedRef.current = false;
      if (redirectTimerRef.current) {
        window.clearTimeout(redirectTimerRef.current);
        redirectTimerRef.current = null;
      }
    };
  }, []);

  // Restore quick-calculator data + last delivery address
  useEffect(() => {
    if (!urlDogId) {
      const data = readQuickCalcFromSession();
      if (data?.form) {
        setInjectedFormData({ ...data.form, _injectTs: Date.now() });
      }
    }

    try {
      const raw = sessionStorage.getItem(SESSION_KEYS.LAST_DELIVERY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed?.city && parsed?.address) {
          setLastDelivery(parsed);
        }
      }
    } catch {
      /* Ignore invalid saved data. */
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ============================================================
  //  🐕 prefill فرم از ?dog_id= در URL
  // ============================================================
  useEffect(() => {
    if (!urlDogId) return;

    const parsedDogId = parseInt(urlDogId, 10);
    if (Number.isNaN(parsedDogId)) return;

    if (prefetchedDogRef.current === parsedDogId) return;

    let hasToken = false;
    try {
      hasToken = Boolean(localStorage.getItem(STORAGE_KEYS.USER_TOKEN));
    } catch {
      hasToken = false;
    }
    if (!hasToken) return;

    let cancelled = false;

    userAxios
      .get(`/api/dogs/${parsedDogId}`)
      .then((res) => {
        if (cancelled || !isMountedRef.current) return;

        const dog = normalizeDogResponse(res.data);
        if (!dog) return;

        prefetchedDogRef.current = parsedDogId;

        const dogForm = {
          dog_id: dog.id,
          dog_name: dog.name || '',
          weight_kg: dog.weight_kg ?? '',
          age_months: dog.age_months ?? '',
          breed: dog.breed || 'medium',
          is_neutered: !!dog.is_neutered,
          bcs: dog.bcs || 'ideal',
          disease: dog.disease || 'healthy',
          allergens: Array.isArray(dog.allergens) ? dog.allergens : [],
          // ✅ NEW: lifestyle fields
          activity: dog.activity || 'moderate',
          pregnancy: dog.pregnancy || 'no',
          surgery: dog.surgery || 'no_surgery',
          temperature: dog.temperature || 'moderate',
          stress: dog.stress || 'low',
        };

        setInitialFormData(dogForm);
        setInjectedFormData({ ...dogForm, _injectTs: Date.now() });
      })
      .catch((err) => {
        if (process.env.NODE_ENV !== 'production') {
          console.warn(
            '[UserApp] Failed to prefetch dog for order:',
            err?.response?.status,
            err?.response?.data?.detail || err?.message
          );
        }
      });

    return () => {
      cancelled = true;
    };
  }, [urlDogId]);

  const handleQuickCalculated = useCallback((result, form) => {
    if (result && form) {
      setInjectedFormData({ ...form, _injectTs: Date.now() });
    }
  }, []);

  const handleFormChange = useCallback((formValues) => {
    setInitialFormData(formValues);
  }, []);

  // ============================================================
  // Calculate order
  // ============================================================
  const handleCalculate = async (formValues) => {
    if (calculationRequestRef.current) return;

    calculationRequestRef.current = true;
    setLoading(true);
    setOrderSubmitted(false);
    setSubmittedOrderId(null);

    try {
      const res = await publicAxios.post('/api/calculate-order', formValues);

      if (!isMountedRef.current) return;

      const newOrderData = { ...res.data, _ts: Date.now() };
      setOrderData(newOrderData);
      setSummaryVisible(true);
      setInitialFormData(formValues);

      try {
        sessionStorage.setItem(
          SESSION_KEYS.QUICK_FORM,
          JSON.stringify(formValues)
        );
        sessionStorage.setItem(
          SESSION_KEYS.QUICK_RESULT,
          JSON.stringify(res.data)
        );
      } catch {
        /* Calculation still succeeds if storage is unavailable. */
      }
    } catch (err) {
      if (!isMountedRef.current) return;

      setSummaryVisible(false);
      setOrderData(null);

      if (process.env.NODE_ENV !== 'production') {
        console.error(
          '[UserApp] Order calculation failed:',
          err.response?.status,
          err.response?.data?.detail || err.message
        );
      }

      toast.error(
        'خطا در محاسبه سفارش: ' +
          (err.response?.data?.detail || err.message)
      );
    } finally {
      calculationRequestRef.current = false;
      if (isMountedRef.current) setLoading(false);
    }
  };

  const handleEditOrder = useCallback(() => {
    setSummaryVisible(false);
  }, []);

  // ============================================================
  // 🛒 افزودن به سبد — بدون آدرس، بدون submit به بک‌اند
  // ============================================================
  const handleAddToCart = useCallback(
    ({ form, summary }) => {
      const result = cart.addItem({ form, summary });

      if (!result.ok) {
        if (result.reason === 'limit') {
          toast.error(
            `حداکثر ${cart.MAX_ITEMS} سفارش می‌تونید در سبد داشته باشید.`
          );
        } else if (result.reason === 'duplicate') {
          toast.error(result.message || 'این سفارش قبلاً به سبد اضافه شده.');
        } else {
          toast.error('خطا در افزودن به سبد.');
        }
        return false;
      }

      toast.success(`«${result.item.dogName}» به سبد خرید اضافه شد.`);

      // ✅ FIX: پاک‌سازی همهٔ pendingهای QuickCalculator
      try {
        sessionStorage.removeItem(SESSION_KEYS.QUICK_FORM);
        sessionStorage.removeItem(SESSION_KEYS.QUICK_RESULT);
        sessionStorage.removeItem(SESSION_KEYS.PENDING_DOG);
      } catch {
        /* ignore */
      }
      setOrderData(null);
      setSummaryVisible(false);
      setInitialFormData(null);

      return true;
    },
    [cart]
  );

  // ============================================================
  // 🚀 Submit order — مسیر مهمان و لاگین‌کرده جدا شد
  // ============================================================
  const handleSubmitOrder = (formValues) => {
    if (!formValues || typeof formValues !== 'object') return;

    if (redirectTimerRef.current) return;

    let hasUserToken = false;
    try {
      hasUserToken = Boolean(localStorage.getItem(STORAGE_KEYS.USER_TOKEN));
    } catch {
      hasUserToken = false;
    }

    // ── مسیر مهمان ─────────────────────────────────────────
    if (!hasUserToken) {
      try {
        sessionStorage.setItem(
          SESSION_KEYS.PENDING_ORDER,
          JSON.stringify(formValues)
        );

        if (
          formValues.dog_name &&
          formValues.weight_kg &&
          formValues.age_months
        ) {
          const pendingDog = {
            dog_name: formValues.dog_name,
            name: formValues.dog_name,
            weight_kg: formValues.weight_kg,
            age_months: formValues.age_months,
            breed: formValues.breed || 'medium',
            is_neutered: Boolean(formValues.is_neutered),
            bcs: formValues.bcs || 'ideal',
            disease: formValues.disease || 'healthy',
            allergens: Array.isArray(formValues.allergens)
              ? formValues.allergens
              : [],
            // ✅ NEW: lifestyle fields
            activity: formValues.activity || 'moderate',
            pregnancy: formValues.pregnancy || 'no',
            surgery: formValues.surgery || 'no_surgery',
            temperature: formValues.temperature || 'moderate',
            stress: formValues.stress || 'low',
          };
          sessionStorage.setItem(
            SESSION_KEYS.PENDING_DOG,
            JSON.stringify(pendingDog)
          );
        }
      } catch {
        /* ignore — redirect still useful */
      }

      toast.success(
        'سفارش شما ذخیره شد. برای تکمیل، لطفاً ثبت‌نام کنید.',
        { duration: TOAST_DURATION }
      );

      redirectTimerRef.current = window.setTimeout(() => {
        if (isMountedRef.current) {
          navigate('/register?next=order', { replace: false });
        }
      }, TOAST_VISIBLE_MS);

      return;
    }

    // ── مسیر لاگین‌کرده ───────────────────────────────────
    setPendingOrderData(formValues);
    setShowAddressModal(true);
  };

  // ============================================================
  // 🚀 Confirm address (فقط برای کاربر لاگین‌کرده)
  // ============================================================
  const handleAddressConfirm = async (deliveryData) => {
    if (!pendingOrderData || submissionRequestRef.current) return;

    submissionRequestRef.current = true;
    setSubmitting(true);

    let navigatingAway = false;
    let submitPayload = null;

    try {
      const {
        customer_address: _oldCustomerAddress,
        delivery_address: _oldDeliveryAddress,
        delivery_city: _oldDeliveryCity,
        delivery_lat: _oldDeliveryLat,
        delivery_lng: _oldDeliveryLng,
        ...cleanOrderData
      } = pendingOrderData;

      submitPayload = {
        ...cleanOrderData,
        delivery_city: deliveryData.city,
        delivery_address: deliveryData.address,
        delivery_lat: deliveryData.lat,
        delivery_lng: deliveryData.lng,
        allergens: Array.isArray(cleanOrderData.allergens)
          ? cleanOrderData.allergens
          : [],
      };

      const res = await userAxios.post('/api/submit-order', submitPayload);

      if (!isMountedRef.current) return;

      const orderId = res.data.order_id;

      try {
        sessionStorage.setItem(
          SESSION_KEYS.LAST_DELIVERY,
          JSON.stringify({
            city: deliveryData.city,
            address: deliveryData.address,
            lat: deliveryData.lat,
            lng: deliveryData.lng,
          })
        );
      } catch {
        /* Saved address is optional. */
      }

      setLastDelivery(deliveryData);
      setOrderData(res.data);
      setOrderSubmitted(true);
      setSubmittedOrderId(orderId);

      setSummaryVisible(false);
      setShowAddressModal(false);
      setPendingOrderData(null);

      clearAllPendingSessions();

      navigatingAway = true;

      redirectTimerRef.current = window.setTimeout(() => {
        if (isMountedRef.current) {
          navigate(`/panel/payment/${orderId}`, { replace: true });
        }
      }, TOAST_VISIBLE_MS);
    } catch (err) {
      if (!isMountedRef.current) return;

      if (err.response?.status === 401 && submitPayload) {
        try {
          sessionStorage.setItem(
            SESSION_KEYS.PENDING_ORDER,
            JSON.stringify(submitPayload)
          );
          sessionStorage.setItem(
            SESSION_KEYS.LAST_DELIVERY,
            JSON.stringify({
              city: deliveryData.city,
              address: deliveryData.address,
              lat: deliveryData.lat,
              lng: deliveryData.lng,
            })
          );

          // ✅ NEW: PENDING_DOG با lifestyle fields
          if (
            submitPayload.dog_name &&
            submitPayload.weight_kg &&
            submitPayload.age_months
          ) {
            const pendingDog = {
              dog_name: submitPayload.dog_name,
              name: submitPayload.dog_name,
              weight_kg: submitPayload.weight_kg,
              age_months: submitPayload.age_months,
              breed: submitPayload.breed || 'medium',
              is_neutered: Boolean(submitPayload.is_neutered),
              bcs: submitPayload.bcs || 'ideal',
              disease: submitPayload.disease || 'healthy',
              allergens: Array.isArray(submitPayload.allergens)
                ? submitPayload.allergens
                : [],
              activity: submitPayload.activity || 'moderate',
              pregnancy: submitPayload.pregnancy || 'no',
              surgery: submitPayload.surgery || 'no_surgery',
              temperature: submitPayload.temperature || 'moderate',
              stress: submitPayload.stress || 'low',
            };
            sessionStorage.setItem(
              SESSION_KEYS.PENDING_DOG,
              JSON.stringify(pendingDog)
            );
          }
        } catch {
          /* ignore */
        }

        setShowAddressModal(false);
        setPendingOrderData(null);

        toast.error(
          'نشست شما منقضی شده است. لطفاً دوباره وارد شوید — سفارش شما حفظ شد.',
          { duration: TOAST_DURATION }
        );

        navigatingAway = true;

        redirectTimerRef.current = window.setTimeout(() => {
          if (isMountedRef.current) {
            navigate('/login?next=order');
          }
        }, TOAST_VISIBLE_MS);
        return;
      }

      toast.error(
        'خطا در ثبت سفارش: ' +
          (err.response?.data?.detail || err.message)
      );
    } finally {
      if (!navigatingAway) {
        submissionRequestRef.current = false;
        if (isMountedRef.current) setSubmitting(false);
      }
    }
  };

  const handleAddressCancel = useCallback(() => {
    if (submitting) return;
    setShowAddressModal(false);
    setPendingOrderData(null);
    submissionRequestRef.current = false;
  }, [submitting]);

  // ============================================================
  // Render
  // ============================================================
  return (
    <div
      dir="rtl"
      className="flex min-h-screen flex-col overflow-x-clip bg-miko-cream text-miko-dark dark:bg-ink-900 dark:text-cream-100"
    >
      <a
        href="#main-content"
        className="sr-only z-[100] rounded-lg bg-miko-cream p-3 text-miko-dark focus:not-sr-only focus:fixed focus:right-4 focus:top-4 dark:bg-ink-800 dark:text-cream-100"
      >
        رفتن به محتوای اصلی
      </a>

      <ToastHost />
      <SiteHeader />

      <main id="main-content" className="flex-1">
        <Hero onCalculated={handleQuickCalculated} />

        <div className="reveal">
          <HowItWorks />
        </div>

        <div className="reveal">
          <BenefitsGrid />
        </div>

        <section
          id="order-form-section"
          className="relative isolate overflow-hidden bg-miko-cream/60 py-12 dark:bg-ink-900 sm:py-16 lg:py-20"
          style={{ scrollMarginTop: `${ORDER_SECTION_SCROLL_OFFSET}px` }}
          aria-labelledby="order-form-title"
        >
          <div
            aria-hidden="true"
            className="pointer-events-none absolute -right-32 top-24 -z-10 h-72 w-72 rounded-full bg-miko-carrot/20 blur-3xl dark:bg-miko-carrot/[0.06]"
          />

          <div className="mx-auto max-w-editorial px-3 sm:px-6 lg:px-8">
            {/* 🛒 بنر سبد خرید */}
            {cart.totalCount > 0 && (
              <div className="mx-auto mb-5 sm:mb-6 max-w-3xl">
                <div className="flex flex-col gap-3 rounded-2xl border border-miko-carrot/40 bg-miko-carrot/10 p-3.5 sm:p-4 shadow-sm dark:border-miko-rust/30 dark:bg-miko-rust/10 sm:flex-row sm:items-center sm:justify-between">
                  <div className="flex min-w-0 items-center gap-3">
                    <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-miko-rust text-white dark:bg-miko-pumpkin dark:text-white">
                      <span className="text-xl" aria-hidden="true">🛒</span>
                    </div>
                    <div className="min-w-0">
                      <p className="text-sm font-black text-miko-rust dark:text-miko-carrot">
                        {toFa(cart.totalCount)} سفارش در سبد شما
                      </p>
                      <p className="mt-0.5 text-xs font-semibold text-miko-rust/80 dark:text-miko-carrot/80">
                        مجموع تقریبی: {toFa(cart.totalAmount)} تومان
                      </p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() => navigate('/cart')}
                    className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-miko-rust px-4 text-sm font-extrabold text-white transition hover:bg-miko-pumpkin focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-miko-rust/40 dark:bg-miko-pumpkin dark:text-white dark:hover:bg-miko-rust"
                  >
                    مشاهده سبد و پرداخت
                    <span aria-hidden="true">←</span>
                  </button>
                </div>
              </div>
            )}

            <header className="mx-auto mb-7 sm:mb-10 max-w-2xl text-center">
              <div className="mb-4 inline-flex items-center gap-2 rounded-full border border-miko-olive/30 bg-miko-olive/10 px-3.5 py-2 text-xs font-bold text-miko-olive dark:border-miko-olive/40 dark:bg-miko-olive/20 dark:text-miko-leaf sm:text-sm">
                <span
                  aria-hidden="true"
                  className="h-2 w-2 rounded-full bg-miko-olive"
                />
                شخصی‌سازی غذای سگ
              </div>

              <h2
                id="order-form-title"
                className="font-display text-2xl font-black leading-tight tracking-tight text-miko-dark dark:text-cream-100 sm:text-3xl lg:text-4xl"
              >
                از اطلاعات سگت تا جزئیات سفارش
              </h2>

              <p className="mx-auto mt-4 max-w-xl text-sm leading-8 text-miko-dark/70 dark:text-cream-300 sm:text-base">
                اطلاعات موردنیاز رو وارد کن، نتیجه محاسبه رو ببین و قبل از
                ثبت سفارش، جزئیات و هزینه رو بررسی کن.
              </p>
            </header>

            <div className="rounded-2xl border border-miko-carrot/25 bg-miko-cream p-2.5 shadow-sm dark:border-dark-700 dark:bg-ink-950/50 sm:rounded-3xl sm:p-5 lg:p-7">
              {!orderSubmitted && (
                <OrderForm
                  orderData={orderData}
                  showSummary={summaryVisible}
                  onEditOrder={handleEditOrder}
                  onSubmit={handleCalculate}
                  onRegisterOrder={handleSubmitOrder}
                  onAddToCart={handleAddToCart}
                  loading={loading}
                  submitting={submitting}
                  orderSubmitted={orderSubmitted}
                  submittedOrderId={submittedOrderId}
                  initialData={initialFormData}
                  onFormChange={handleFormChange}
                  injectedData={injectedFormData}
                />
              )}

              {orderSubmitted && submittedOrderId && (
                <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-miko-olive via-miko-olive to-miko-leaf p-5 text-white sm:rounded-3xl sm:p-10">
                  <div
                    aria-hidden="true"
                    className="pointer-events-none absolute -left-16 -top-16 h-48 w-48 rounded-full bg-white/[0.08]"
                  />

                  <div className="relative mx-auto max-w-lg text-center">
                    <div
                      aria-hidden="true"
                      className="mx-auto mb-4 sm:mb-5 flex h-16 w-16 items-center justify-center rounded-full border border-white/25 bg-white/15 p-4 text-3xl sm:h-20 sm:w-20 sm:p-5 sm:text-4xl"
                    >
                      <SiteImage
                        imageKey="icon_check"
                        fallback="✓"
                        alt=""
                        className="w-full h-full object-contain brightness-0 invert"
                      />
                    </div>

                    <h3 className="font-display text-lg font-black sm:text-2xl">
                      سفارشت با موفقیت ثبت شد!
                    </h3>

                    <p className="mt-3 text-sm leading-7 text-white/80">
                      سفارش تو ثبت شده. برای تکمیل فرایند، به صفحه پرداخت
                      برو.
                    </p>

                    <div className="mt-4 sm:mt-5 inline-flex items-center gap-3 rounded-xl border border-white/20 bg-white/10 px-3.5 sm:px-4 py-2.5 sm:py-3">
                      <span className="text-xs sm:text-sm text-white/80">شماره سفارش</span>
                      <strong className="font-mono text-base sm:text-lg">
                        #{submittedOrderId}
                      </strong>
                    </div>

                    <p className="mt-4 text-xs text-white/75">
                      در حال انتقال به صفحه پرداخت...
                    </p>

                    <button
                      type="button"
                      onClick={() =>
                        navigate(`/panel/payment/${submittedOrderId}`)
                      }
                      className="mt-5 sm:mt-6 inline-flex min-h-12 w-full items-center justify-center gap-2 rounded-xl bg-white px-5 sm:px-6 py-3 text-sm font-black text-miko-olive transition hover:bg-miko-cream focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white focus-visible:ring-offset-2 focus-visible:ring-offset-miko-olive sm:w-auto"
                    >
                      <span className="w-4 h-4 flex-shrink-0" aria-hidden="true">
                        <SiteImage
                          imageKey="icon_payment"
                          fallback="💳"
                          alt=""
                          className="w-full h-full object-contain"
                        />
                      </span>
                      رفتن به صفحه پرداخت
                      <span aria-hidden="true">←</span>
                    </button>
                  </div>
                </div>
              )}
            </div>

            <p className="mt-5 text-center text-xs leading-6 text-miko-dark/60 dark:text-cream-400 sm:text-sm">
              قیمت و جزئیات سفارش رو قبل از تأیید نهایی بررسی کن.
            </p>
          </div>
        </section>

        <div className="reveal">
          <Testimonials />
        </div>

        <div className="reveal">
          <FAQAccordion />
        </div>
      </main>

      <SiteFooter />

      <AddressModal
        isOpen={showAddressModal}
        onClose={handleAddressCancel}
        onConfirm={handleAddressConfirm}
        loading={submitting}
        initialDelivery={lastDelivery}
      />
    </div>
  );
}