// ✅ v5: Code Splitting پیشرفته برای بهبود PageSpeed
//  - تقسیم main.js به چند chunk کوچیک‌تر
//  - Lazy load همه روت‌ها به‌جز صفحه اصلی
//  - Prefetch هوشمند برای روت‌های پرکاربر
// ============================================================

import React, { useState, useEffect, lazy, Suspense } from 'react';
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate,
  useLocation,
} from 'react-router-dom';

// ============================================================
//  📦 Eager imports (فقط UserApp و ScrollToTop - خیلی کوچیک)
// ============================================================
import UserApp from './user/UserApp';

// ============================================================
//  🎯 Lazy imports - همه چیز lazy load می‌شه
// ============================================================

// کامپوننت‌های مشترک
const Cart = lazy(() => import(
  /* webpackChunkName: "cart" */
  /* webpackPrefetch: true */
  './user/pages/Cart'
));
const NotFound = lazy(() => import(
  /* webpackChunkName: "not-found" */
  './user/pages/NotFound'
));

// پنل ادمین
const AdminApp = lazy(() => import(
  /* webpackChunkName: "admin" */
  './admin/AdminApp'
));
const AdminLogin = lazy(() => import(
  /* webpackChunkName: "admin-auth" */
  './admin/AdminLogin'
));

// پنل کاربر
const UserPanel = lazy(() => import(
  /* webpackChunkName: "user-panel" */
  /* webpackPrefetch: true */
  './user/UserPanel'
));
const UserLogin = lazy(() => import(
  /* webpackChunkName: "user-auth" */
  /* webpackPrefetch: true */
  './user/UserLogin'
));
const UserRegister = lazy(() => import(
  /* webpackChunkName: "user-auth" */
  /* webpackPrefetch: true */
  './user/UserRegister'
));

// ============================================================
//  🎨 LoadingFallback
// ============================================================
function LoadingFallback() {
  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: '#F9F6F0',
        zIndex: 9999,
      }}
    >
      <div
        style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: '16px',
        }}
      >
        <div
          style={{
            width: '48px',
            height: '48px',
            border: '4px solid #F2D6AE',
            borderTopColor: '#AF6B24',
            borderRadius: '50%',
            animation: 'miko-spin 0.8s linear infinite',
          }}
        />
        <span
          style={{
            fontFamily: 'Peyda, Tahoma, sans-serif',
            fontSize: '14px',
            fontWeight: 500,
            color: '#764418',
          }}
        >
          در حال بارگذاری میکو…
        </span>
      </div>
      <style>
        {`
          @keyframes miko-spin {
            to { transform: rotate(360deg); }
          }
        `}
      </style>
    </div>
  );
}

// ============================================================
//  🎯 ScrollToTop
// ============================================================
const HEADER_OFFSET = 96;
const MAX_SCROLL_ATTEMPTS = 20;
const SCROLL_RETRY_DELAY = 50;

function ScrollToTop() {
  const location = useLocation();
  const { pathname, hash, key } = location;

  useEffect(() => {
    if (!hash) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    const id = hash.replace(/^#/, '');
    if (!id) {
      window.scrollTo({ top: 0, behavior: 'instant' });
      return;
    }

    let cancelled = false;
    let attempts = 0;
    let timer = null;

    const tryScroll = () => {
      if (cancelled) return;

      const el = document.getElementById(id);
      if (el) {
        const top =
          el.getBoundingClientRect().top +
          window.pageYOffset -
          HEADER_OFFSET;
        window.scrollTo({
          top: Math.max(0, top),
          behavior: 'smooth',
        });
        return;
      }

      attempts += 1;
      if (attempts < MAX_SCROLL_ATTEMPTS) {
        timer = setTimeout(tryScroll, SCROLL_RETRY_DELAY);
      }
    };

    const raf = requestAnimationFrame(tryScroll);

    return () => {
      cancelled = true;
      cancelAnimationFrame(raf);
      if (timer) clearTimeout(timer);
    };
  }, [pathname, hash, key]);

  return null;
}

// ============================================================
//  🔒 Route Guards
// ============================================================
function ProtectedRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));

  if (!isLoggedIn) {
    return <Navigate to="/login?next=panel" replace />;
  }

  return children;
}

function AdminRoute({ children }) {
  const [isAdmin, setIsAdmin] = useState(
    () => !!localStorage.getItem('adminToken')
  );

  useEffect(() => {
    const handler = () => setIsAdmin(!!localStorage.getItem('adminToken'));
    window.addEventListener('storage', handler);
    window.addEventListener('adminAuthUpdated', handler);
    return () => {
      window.removeEventListener('storage', handler);
      window.removeEventListener('adminAuthUpdated', handler);
    };
  }, []);

  if (!isAdmin) {
    return <Navigate to="/admin/login" replace />;
  }

  return children;
}

function PublicOnlyRoute({ children }) {
  const [isLoggedIn] = useState(() => !!localStorage.getItem('userToken'));

  if (isLoggedIn) {
    return <Navigate to="/panel" replace />;
  }

  return children;
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
function AppContent() {
  return (
    <>
      <ScrollToTop />
      <Suspense fallback={<LoadingFallback />}>
        <Routes>
          {/* صفحه اصلی - همیشه eager */}
          <Route path="/" element={<UserApp />} />

          {/* سبد خرید */}
          <Route path="/cart" element={<Cart />} />

          {/* احراز هویت کاربر */}
          <Route
            path="/login"
            element={
              <PublicOnlyRoute>
                <UserLogin />
              </PublicOnlyRoute>
            }
          />
          <Route
            path="/register"
            element={
              <PublicOnlyRoute>
                <UserRegister />
              </PublicOnlyRoute>
            }
          />

          {/* پنل کاربر */}
          <Route
            path="/panel/*"
            element={
              <ProtectedRoute>
                <UserPanel />
              </ProtectedRoute>
            }
          />

          {/* پنل ادمین */}
          <Route path="/admin/login" element={<AdminLogin />} />
          <Route
            path="/admin/*"
            element={
              <AdminRoute>
                <AdminApp />
              </AdminRoute>
            }
          />

          {/* 404 */}
          <Route path="*" element={<NotFound />} />
        </Routes>
      </Suspense>
    </>
  );
}

// ============================================================
//  Root App
// ============================================================
export default function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}
